package main

import (
	"fmt"
	"math"
)

func main() {
	var n, m, a, b int
	fmt.Scan(&n, &m, &a, &b)

	// Option 1: Buy only single tickets
	cost1 := n * a

	// Option 2: Buy only m-ride tickets (buy enough to cover n rides)
	numTickets := (n + m - 1) / m
	cost2 := numTickets * b

	// Option 3: Mix of m-ride tickets and single tickets
	// Try all possible numbers of m-ride tickets from 0 to ceil(n/m)
	minCost := math.MaxInt
	for i := 0; i <= (n+m-1)/m; i++ {
		ridesCovered := i * m
		if ridesCovered > n {
			break
		}
		remaining := n - ridesCovered
		cost := i*b + remaining*a
		if cost < minCost {
			minCost = cost
		}
	}

	// The minimum is the min of all options
	result := minCost
	if cost1 < result {
		result = cost1
	}
	if cost2 < result {
		result = cost2
	}

	fmt.Println(result)
}
